import{Z as a,e as s,f as t,a0 as n}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Spam Keywords in Detail","description":"","frontmatter":{},"headers":[],"relativePath":"guides/configuration/spam-keywords-in-detail.md","filePath":"guides/configuration/spam-keywords-in-detail.md","lastUpdated":1782532814000}'),i={name:"guides/configuration/spam-keywords-in-detail.md"};function o(l,e,r,p,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="spam-keywords-in-detail" tabindex="-1">Spam Keywords in Detail <a class="header-anchor" href="#spam-keywords-in-detail" aria-label="Permalink to &quot;Spam Keywords in Detail&quot;">​</a></h1><p>Spam keywords are Formie&#39;s built-in content screening tool — match words, phrases, boolean logic, or IP addresses against a submission and mark it as spam during the <strong><code>screen</code></strong> workflow stage. This guide covers full syntax, real-world rule sets, and how keywords fit alongside email rules, text rules, guards, and captchas.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/forms/spam-protection">Spam Protection</a></li><li><a href="/forms/submission-screening">Submission Screening</a> — where <code>screen.runSpamChecks</code> runs</li></ul><p>Configure keywords under <strong>Formie → Settings → Spam Protection → Content Rules → Spam Keywords</strong>. Values live in Formie&#39;s <a href="/guides/configuration/project-config-environment-and-control-panel-settings">control panel settings store</a> — not in <code>config/formie.php</code> by default.</p><h2 id="how-matching-works" tabindex="-1">How Matching Works <a class="header-anchor" href="#how-matching-works" aria-label="Permalink to &quot;How Matching Works&quot;">​</a></h2><ol><li>A visitor submits a form</li><li>Field validation passes</li><li>During <strong><code>screen.runSpamChecks</code></strong>, <code>SpamHelper</code> evaluates keyword and IP rules against submission content</li><li>On match, the submission is marked spam with a reason; behaviour follows <strong>Spam submission behavior</strong> (show success or show message)</li></ol><p>Keywords check the <strong>whole submission</strong> — all field values combined — not individual fields in isolation.</p><p>Evaluation order within spam checks (simplified): email rules → text rules → spam keywords → captcha/scoring integrations. See <a href="/forms/submission-screening">Submission Screening</a> for the full pipeline.</p><h2 id="keyword-definition-syntax" tabindex="-1">Keyword Definition Syntax <a class="header-anchor" href="#keyword-definition-syntax" aria-label="Permalink to &quot;Keyword Definition Syntax&quot;">​</a></h2><p>One rule per line. Lines starting with <code>#</code> are comments.</p><h3 id="simple-word-match" tabindex="-1">Simple Word Match <a class="header-anchor" href="#simple-word-match" aria-label="Permalink to &quot;Simple Word Match&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Flags content containing the word &quot;spam&quot;. Does not match &quot;spamming&quot; or &quot;Spam&quot;.</span></span>
<span class="line"><span>[match: spam]</span></span></code></pre></div><p>Matching is case-sensitive for the term as written. Use separate lines for case variants if needed.</p><h3 id="exact-phrase" tabindex="-1">Exact Phrase <a class="header-anchor" href="#exact-phrase" aria-label="Permalink to &quot;Exact Phrase&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Flags content containing the exact phrase &quot;cheap ham&quot;</span></span>
<span class="line"><span>[match: cheap ham]</span></span></code></pre></div><h3 id="boolean-and" tabindex="-1">Boolean AND <a class="header-anchor" href="#boolean-and" aria-label="Permalink to &quot;Boolean AND&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Flags content only if both &quot;spam&quot; and &quot;bulk&quot; are present</span></span>
<span class="line"><span>[match: spam AND bulk]</span></span></code></pre></div><h3 id="boolean-or" tabindex="-1">Boolean OR <a class="header-anchor" href="#boolean-or" aria-label="Permalink to &quot;Boolean OR&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Flags content if either &quot;spam&quot; or &quot;phishing&quot; is present</span></span>
<span class="line"><span>[match: spam OR phishing]</span></span></code></pre></div><h3 id="grouped-logic" tabindex="-1">Grouped Logic <a class="header-anchor" href="#grouped-logic" aria-label="Permalink to &quot;Grouped Logic&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Flags content if it contains either &quot;spam&quot; or &quot;junk&quot; along with &quot;email&quot;</span></span>
<span class="line"><span>[match: (spam OR junk) AND email]</span></span></code></pre></div><p>Use parentheses to group when mixing AND and OR.</p><h3 id="not" tabindex="-1">NOT <a class="header-anchor" href="#not" aria-label="Permalink to &quot;NOT&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Flags content if it does not contain &quot;client&quot;</span></span>
<span class="line"><span>[match: NOT client]</span></span></code></pre></div><p>Useful for allowlist-style exceptions combined with other rules on separate lines (each line is evaluated).</p><h2 id="ip-address-rules" tabindex="-1">IP Address Rules <a class="header-anchor" href="#ip-address-rules" aria-label="Permalink to &quot;IP Address Rules&quot;">​</a></h2><p>Match the submitter&#39;s IP — supports singular addresses, lists, ranges, and CIDR notation.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Single IP</span></span>
<span class="line"><span>[ip: 192.168.0.1]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Multiple IPs</span></span>
<span class="line"><span>[ip: 192.168.0.1, 192.168.0.2, 192.168.0.3]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Range</span></span>
<span class="line"><span>[ip: 192.168.0.1-192.168.0.255]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># CIDR</span></span>
<span class="line"><span>[ip: 192.168.0.0/24]</span></span></code></pre></div><p>IP rules are evaluated alongside <code>[match:]</code> rules during <code>screen.runSpamChecks</code>.</p><h2 id="referencing-external-content" tabindex="-1">Referencing External Content <a class="header-anchor" href="#referencing-external-content" aria-label="Permalink to &quot;Referencing External Content&quot;">​</a></h2><p>Keywords are stored in control panel settings, which are awkward to edit on production when project-scoped. Reference a Global Set field instead:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{forms.spamKeywords}</span></span></code></pre></div><p>If you have a Global Set <code>Forms</code> with field handle <code>spamKeywords</code>, Formie pulls keyword lines from that field — content editors update rules without deploys.</p><p>Field/global references work in keyword lines the same way as other Formie reference tokens.</p><h2 id="real-world-rule-sets" tabindex="-1">Real-World Rule Sets <a class="header-anchor" href="#real-world-rule-sets" aria-label="Permalink to &quot;Real-World Rule Sets&quot;">​</a></h2><h3 id="obvious-junk-phrases" tabindex="-1">Obvious Junk Phrases <a class="header-anchor" href="#obvious-junk-phrases" aria-label="Permalink to &quot;Obvious Junk Phrases&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Common SEO spam</span></span>
<span class="line"><span>[match: buy followers]</span></span>
<span class="line"><span>[match: (viagra OR cialis) AND cheap]</span></span>
<span class="line"><span>[match: crypto AND guaranteed returns]</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Phishing patterns</span></span>
<span class="line"><span>[match: verify your account AND click]</span></span>
<span class="line"><span>[match: suspended AND immediately]</span></span></code></pre></div><h3 id="competitor-abuse-blocklist" tabindex="-1">Competitor / Abuse Blocklist <a class="header-anchor" href="#competitor-abuse-blocklist" aria-label="Permalink to &quot;Competitor / Abuse Blocklist&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Block specific domains mentioned in message fields</span></span>
<span class="line"><span>[match: competitor-domain.com]</span></span>
<span class="line"><span>[match: spammer-network.net]</span></span></code></pre></div><p>Combine with <a href="/forms/spam-protection#email-rules">Email Rules</a> blocked domains for defence in depth.</p><h3 id="internal-test-exclusions" tabindex="-1">Internal Test Exclusions <a class="header-anchor" href="#internal-test-exclusions" aria-label="Permalink to &quot;Internal Test Exclusions&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Flag everything EXCEPT submissions mentioning our client code</span></span>
<span class="line"><span>[match: NOT ACME-2026]</span></span></code></pre></div><p>Use carefully — broad NOT rules can have unexpected matches. Test with saved spam review enabled.</p><h3 id="office-ip-allowlist-complement" tabindex="-1">Office IP Allowlist Complement <a class="header-anchor" href="#office-ip-allowlist-complement" aria-label="Permalink to &quot;Office IP Allowlist Complement&quot;">​</a></h3><p>Keywords do not allowlist IPs — they only flag. For office IPs that should never be blocked by keywords, rely on IP rules only targeting bad actors, not inverted NOT patterns.</p><p>Pair IP <strong>block</strong> rules with throttling instead:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Known bad range from repeat attacks</span></span>
<span class="line"><span>[ip: 203.0.113.0/24]</span></span></code></pre></div><h3 id="editor-managed-list-via-global-set" tabindex="-1">Editor-Managed List via Global Set <a class="header-anchor" href="#editor-managed-list-via-global-set" aria-label="Permalink to &quot;Editor-Managed List via Global Set&quot;">​</a></h3><p>In the Global Set rich text or plain text field:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[match: word1]</span></span>
<span class="line"><span>[match: word2 AND word3]</span></span></code></pre></div><p>In <strong>Spam Keywords</strong> setting:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{siteSettings.spamKeywordList}</span></span></code></pre></div><p>Editors update the Global Set; Formie reads it at screening time.</p><h2 id="spam-behaviour-settings" tabindex="-1">Spam Behaviour Settings <a class="header-anchor" href="#spam-behaviour-settings" aria-label="Permalink to &quot;Spam Behaviour Settings&quot;">​</a></h2><p>Keywords mark submissions as spam — they do not delete them. Related plugin settings:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><code>saveSpam</code></td><td>Store spam submissions for review</td></tr><tr><td><code>spamLimit</code></td><td>Cap stored spam count</td></tr><tr><td><code>spamBehaviour</code></td><td><code>showSuccess</code> (default) or <code>showMessage</code></td></tr><tr><td><code>spamBehaviourMessage</code></td><td>Custom message when showing rejection</td></tr><tr><td><code>spamEmailNotifications</code></td><td>Whether spam still triggers email</td></tr></tbody></table><p>Showing success to spammers avoids teaching bots which rules fired.</p><h2 id="what-keywords-do-not-replace" tabindex="-1">What Keywords Do Not Replace <a class="header-anchor" href="#what-keywords-do-not-replace" aria-label="Permalink to &quot;What Keywords Do Not Replace&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Use for</th></tr></thead><tbody><tr><td><a href="/forms/spam-protection#email-rules">Email rules</a></td><td>Blocked/allowed domains globally</td></tr><tr><td><a href="/forms/spam-protection#text-rules">Text rules</a></td><td>Keyboard spam, link count limits</td></tr><tr><td><a href="/forms/spam-protection#submission-guards">Submission guards</a></td><td>Honeypot, timing, replay</td></tr><tr><td><a href="/forms/spam-protection#submission-throttling">Submission throttling</a></td><td>Flood protection</td></tr><tr><td><a href="/integrations/captchas/">Captcha integrations</a></td><td>Strong bot challenges</td></tr><tr><td><a href="/forms/submission-limits">Submission limits</a></td><td>Business quotas (not spam)</td></tr></tbody></table><p>Keywords excel at recurring phrases and known bad IPs — not at behavioural bot detection alone.</p><h2 id="headless-and-graphql" tabindex="-1">Headless and GraphQL <a class="header-anchor" href="#headless-and-graphql" aria-label="Permalink to &quot;Headless and GraphQL&quot;">​</a></h2><p>Keyword screening runs server-side for all submit paths — browser, client REST, and GraphQL. No front-end configuration required.</p><p>Browser-only guards (honeypot, minimum submit time) do <strong>not</strong> run on GraphQL; keywords and captchas still do.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>False positives</strong></p><ul><li>Enable <code>saveSpam</code> and review flagged submissions</li><li>Narrow rules — replace broad <code>[match: http]</code> with <code>[match: (viagra OR casino)]</code></li><li>Add allowed terms via Text Rules <strong>Allowed terms</strong> for product codes caught by suspicious text detection</li></ul><p><strong>Rule not firing</strong></p><ul><li>Confirm the keyword setting is saved on the correct site scope (multi-site)</li><li>Check Global Set reference resolves on production</li><li>Verify screening stage is not skipped by an earlier workflow customisation</li></ul><p><strong>Keywords lost after deploy</strong></p><ul><li>Confirm keywords are saved under <strong>Settings → Spam Protection</strong>, not in project config YAML</li><li>See <a href="/guides/configuration/project-config-environment-and-control-panel-settings">Project config, environment, and control panel settings</a></li></ul>`,71)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
